import sys

def main():
    import sys
    import bisect

    input = sys.stdin.read().split()
    n = int(input[0])
    hashtags = input[1:]

    result = []
    for hashtag in hashtags:
        stripped = hashtag[1:]
        pos = bisect.bisect_right(result, stripped)
        if pos < len(result):
            result[pos] = stripped
        else:
            result.append(stripped)

    current = ''
    output = []
    for hashtag in hashtags:
        stripped = hashtag[1:]

        while result and result[-1] > stripped:
            result.pop()

        if not result:
            output.append('#')
        elif result[-1] >= stripped:
            output.append('#' + result[-1])
        else:
            pos = bisect.bisect_left(result, stripped)
            output.append('#' + result[pos])
            current = result[pos]

    for hashtag in output:
        print(hashtag)

main()
